// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Login Đăng nhập bằng tài khoản `users` (bcrypt)
	// (POST /v1/auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Thu hồi refresh token (cả chuỗi xoay vòng)
	// (POST /v1/auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// RefreshToken Đổi refresh token lấy cặp token mới (xoay vòng refresh token)
	// (POST /v1/auth/refresh)
	RefreshToken(ctx context.Context, request RefreshTokenRequestObject) (RefreshTokenResponseObject, error)
	// ListFilterAccounts Tài khoản trong phạm vi người dùng (cho bộ lọc)
	// (GET /v1/filters/accounts)
	ListFilterAccounts(ctx context.Context, request ListFilterAccountsRequestObject) (ListFilterAccountsResponseObject, error)
	// ListFilterCampaigns Chiến dịch có link thuộc phạm vi người dùng
	// (GET /v1/filters/campaigns)
	ListFilterCampaigns(ctx context.Context, request ListFilterCampaignsRequestObject) (ListFilterCampaignsResponseObject, error)
	// ListFilterPrefixes Danh sách prefix (`sale`, `lm`, …)
	// (GET /v1/filters/prefixes)
	ListFilterPrefixes(ctx context.Context, request ListFilterPrefixesRequestObject) (ListFilterPrefixesResponseObject, error)
	// GetLinkQrcode Mã QR của short URL (PNG)
	// (GET /v1/links/{code}/qrcode)
	GetLinkQrcode(ctx context.Context, request GetLinkQrcodeRequestObject) (GetLinkQrcodeResponseObject, error)
	// GetMe Người dùng hiện tại + phạm vi dữ liệu
	// (GET /v1/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// ListAccountReports R2 — Danh sách tài khoản kèm chỉ số
	// (GET /v1/reports/accounts)
	ListAccountReports(ctx context.Context, request ListAccountReportsRequestObject) (ListAccountReportsResponseObject, error)
	// GetAccountReport R2 — Chi tiết tài khoản
	// (GET /v1/reports/accounts/{username})
	GetAccountReport(ctx context.Context, request GetAccountReportRequestObject) (GetAccountReportResponseObject, error)
	// ListCampaignReports R3 — Danh sách chiến dịch kèm chỉ số
	// (GET /v1/reports/campaigns)
	ListCampaignReports(ctx context.Context, request ListCampaignReportsRequestObject) (ListCampaignReportsResponseObject, error)
	// CompareCampaigns R3 — So sánh 2–5 chiến dịch
	// (GET /v1/reports/campaigns/compare)
	CompareCampaigns(ctx context.Context, request CompareCampaignsRequestObject) (CompareCampaignsResponseObject, error)
	// GetCampaignReport R3 — Chi tiết chiến dịch
	// (GET /v1/reports/campaigns/{code})
	GetCampaignReport(ctx context.Context, request GetCampaignReportRequestObject) (GetCampaignReportResponseObject, error)
	// ListClicks R6 — Nhật ký click thô (≤ 3 tháng), phân trang con trỏ; IP che theo vai trò
	// (GET /v1/reports/clicks)
	ListClicks(ctx context.Context, request ListClicksRequestObject) (ListClicksResponseObject, error)
	// GetClickFacets R6b — Giá trị cho bộ lọc (theo phạm vi); field=param.<key> cho tham số URL
	// (GET /v1/reports/clicks/facets)
	GetClickFacets(ctx context.Context, request GetClickFacetsRequestObject) (GetClickFacetsResponseObject, error)
	// QueryClicks R6b — Click Explorer — lọc nhiều tiêu chí, nhóm theo 1–3 chiều, top N + "khác", so kỳ trước
	// (POST /v1/reports/clicks/query)
	QueryClicks(ctx context.Context, request QueryClicksRequestObject) (QueryClicksResponseObject, error)
	// ListCtvReports R4 — Bảng xếp hạng CTV (không gồm "chưa định danh")
	// (GET /v1/reports/ctvs)
	ListCtvReports(ctx context.Context, request ListCtvReportsRequestObject) (ListCtvReportsResponseObject, error)
	// LookupCtv R4 — Tra cứu CTV theo SĐT (mọi định dạng) / hash — khớp chính xác qua index ctv_id
	// (GET /v1/reports/ctvs/lookup)
	LookupCtv(ctx context.Context, request LookupCtvRequestObject) (LookupCtvResponseObject, error)
	// GetUnidentifiedCtv R4 — Link / click chưa định danh CTV (admin, chính chủ)
	// (GET /v1/reports/ctvs/unidentified)
	GetUnidentifiedCtv(ctx context.Context, request GetUnidentifiedCtvRequestObject) (GetUnidentifiedCtvResponseObject, error)
	// GetCtvReport R4 — Chi tiết CTV (ref = ctv_ref mờ, không phải SĐT)
	// (GET /v1/reports/ctvs/{ref})
	GetCtvReport(ctx context.Context, request GetCtvReportRequestObject) (GetCtvReportResponseObject, error)
	// ListTopLinks R5 — Top link theo click / tăng trưởng; link "chết" (không click N ngày)
	// (GET /v1/reports/links/top)
	ListTopLinks(ctx context.Context, request ListTopLinksRequestObject) (ListTopLinksResponseObject, error)
	// GetLinkReport R5 — Chi tiết link (KPI, timeline, phân rã, 100 click gần nhất)
	// (GET /v1/reports/links/{code})
	GetLinkReport(ctx context.Context, request GetLinkReportRequestObject) (GetLinkReportResponseObject, error)
	// GetOverview R1 — Tổng quan (KPI, timeline, top, phân rã, heatmap) theo phạm vi
	// (GET /v1/reports/overview)
	GetOverview(ctx context.Context, request GetOverviewRequestObject) (GetOverviewResponseObject, error)
	// ListParamReports §4.1 c2 — Tham số URL đang theo dõi kèm số giá trị, số link, tổng click
	// (GET /v1/reports/params)
	ListParamReports(ctx context.Context, request ListParamReportsRequestObject) (ListParamReportsResponseObject, error)
	// GetParamReport §4.1 c2 — Giá trị của một tham số + chỉ số, timeline top 5, cảnh báo dữ liệu
	// (GET /v1/reports/params/{key})
	GetParamReport(ctx context.Context, request GetParamReportRequestObject) (GetParamReportResponseObject, error)
	// ListSavedReports Báo cáo / bộ lọc đã lưu của tôi
	// (GET /v1/saved-reports)
	ListSavedReports(ctx context.Context, request ListSavedReportsRequestObject) (ListSavedReportsResponseObject, error)

	// (POST /v1/saved-reports)
	CreateSavedReport(ctx context.Context, request CreateSavedReportRequestObject) (CreateSavedReportResponseObject, error)
	// GetSharedReport Mở báo cáo được chia sẻ — người nhận chỉ thấy dữ liệu thuộc phạm vi của mình khi chạy
	// (GET /v1/saved-reports/shared/{token})
	GetSharedReport(ctx context.Context, request GetSharedReportRequestObject) (GetSharedReportResponseObject, error)

	// (DELETE /v1/saved-reports/{id})
	DeleteSavedReport(ctx context.Context, request DeleteSavedReportRequestObject) (DeleteSavedReportResponseObject, error)

	// (GET /v1/saved-reports/{id})
	GetSavedReport(ctx context.Context, request GetSavedReportRequestObject) (GetSavedReportResponseObject, error)

	// (PATCH /v1/saved-reports/{id})
	UpdateSavedReport(ctx context.Context, request UpdateSavedReportRequestObject) (UpdateSavedReportResponseObject, error)
	// ShareSavedReport Bật / tắt chia sẻ qua link
	// (POST /v1/saved-reports/{id}/share)
	ShareSavedReport(ctx context.Context, request ShareSavedReportRequestObject) (ShareSavedReportResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// Login operation middleware
func (sh *strictHandler) Login(w http.ResponseWriter, r *http.Request) {
	var request LoginRequestObject

	var body LoginJSONRequestBody
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		sh.options.RequestErrorHandlerFunc(w, r, fmt.Errorf("can't decode JSON body: %w", err))
		return
	}
	request.Body = &body

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.Login(ctx, request.(LoginRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "Login")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(LoginResponseObject); ok {
		if err := validResponse.VisitLoginResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

